Rules.InvariantScript:
With(
    {c: varOpenTicket.Cur},
    ForAll(
        Sequence(4),
        With(
            {n: Value},
            {
                Step: n,
                Name: Switch(n, 1, "Submitted", 2, "Review", 3, If(varOpenTicket.Src = "Locksmith", "Locksmith", "In progress"), "Done"),
                Role: Switch(n, 1, "Request submitted", 2, "Supervisor review", 3, "Work in progress", "Request completed"),
                St: If(c >= 5, "complete", n < c, "done", n = c, "current", "waiting")
            }
        )
    )
)
